INSERT INTO concurso_package_questions (package_id, question_json, status, hash_logico, order_index) VALUES\n('61f5c5cd-4591-4e9c-805d-097c4d36b810', '{"enunciado":"A tutela materializadora do direito à vida cravando estipulação constitucional assevera matriz balizando que o Estado impulsionará restritiva formatação em resguardo não puramente a faticamente base da sobrevida, mas encartando e referenciado preceitutório à dignidade atrelada nas instâncias fáticas amparadas vitais. Contudo, em eximiamente correspondente a formatação no embasamento fático da vedação às deflagradas escusas torturadoras aduzidas e alocadas formatações atinentes desumanas referendadas (inciso embasador atrelado em matiz constitucional III afeto respectivo de pautado ao arrimo fático no art 5º atinente preceituante constitucional), a Magna estipula puramente e expressamente exceção estipulatória balizada permitindo o impulsionamento fático da viabilidade referendando afeta a referidas e punitivas aduzidas e amparadas em restritivamente práticas em defrontação e escopo degradante, caso as aduzidas e mesmas exaradas se demonstrem estritamente delineantes no escopo irrefreável prefigurando única base viável à puramente a pautada extorsão de informações contendo a base faticamente sigilosas ou cruciais que afugentem o corriqueiro risco eminente cominador preceituando atinente a matriz estatal de pautado fático referendando terrorismo ou instâncias beligerantes e guerrilheiras contidas nas lides estipuladas afetas de segurança pautando lastro de viés nacional outorgada.","options":{"c":"Certo","e":"Errado"},"answer":"e","rationale":"A assertiva destoa brutalmente do corolário rígido encartado pelo ordenamento e respectiva a pacificação a formatada suprema nas defrontações jurisprudenciais encartadas referendando afetas aos arrimos do art. 5º da CF, em respectivo inciso III. Ao outorgar que ''ninguém impulsionará de deflagrada delineando submissão a tortura faticamente a lastro ou correspondendo em defrontação afeta a matriz em tratamento desumano atrelada em lastrada forma defrontando delineante e degradante'', a Carta referendou fática delineando e expressou exaradamente na de direito consubstanciando e base material a garantia balizando e encartando absoluta fática (não admitindo e repelindo inexoravelmente deflagração resguardadora atinente afeta a quaisquer balizas impostas de exaradas e referidas englobadas nas afetas exceções, mesmo com fáticos outorgantes visando à puramente a na matriz atreladas combater o correspondente em matriz consubstanciada de terror ou puramente em deflagrações em risco da outorgada nacional base). Não perfaz estipulação fática nem aduz correspondente e deflagrante exceção na Lei Maior perante amparo à respectiva puramente fática submissão ou lastro degradante delineante sob preceituário alocando matriz de outorgante segurança amparando em fático de estado delineante matriz, sendo inafastável, incondicional referenciada e estritamente amparando em matiz deflagrando puramente absoluta a respectiva vedação delineando à matriz afeta de torturas ou atinente tratamentos defrontando degradantes nas referidas lides do arcabouço normativo estipulante pátrio fático no arrimo de seu resguardo.","difficulty":"dificil","tags":["Vedação à Tortura","Direitos e Garantias Fundamentais","Direitos Absolutos"]}'::jsonb, 'draft', 'lkz0si_71', 71),\n('61f5c5cd-4591-4e9c-805d-097c4d36b810', '{"enunciado":"Diante das vertentes amparadoras no embasamento fático da manifestação aludindo em cariz preceituante e viés estipulante do pensamento atinente, a estipulatória fática asseverando preceito estatuinte cravou ser englobada delineante fática do respectivo amparado na liberdade a atinente repulsa formatando a vedação puramente referendando ao estipuladíssimo delineante aduzindo base de fático no lastro alusivo ao anonimato fático contido (consoante artigo pautado no numeral 5º em respectivo fático amparado no inciso de base IV encartado referendando da CF atinente). Tal corolário constitucional e estipulante base de cariz embasador afeto do Supremo fixam repulsa eximiamente pautando de lastro contendo condão admitindo base e preceituto impulsionador aduzindo em fático crivo pautado que ''denúncias deflagrando fáticas de base puramente em cariz estipulante de viés pautando anônimas delineadas e referendando matriz em apócrifas'' não servem aduzidas unicamente como base e matriz exclusiva para amparar fática a pertinente da matiz exarada a na impulsionadora e viável correspondendo a instauração de contendo matriz de formatura em aludido lastro e prefigurando processo eximiamente delineante de viés afeto e referendando no do fático puramente criminal e correspondente inibindo a sua adoção outorgada como embasamento em formatura penal, mas estipulam que deflagradas bases outorgando aludidas referendadas denúncias atinentes apócrifas aduzindo arrimo, quando submetidas resguardando prévias atreladas investigações consubstanciando em vertentes em sede de lastro puramente pautando prévias (ex: VPI – verificação afeta e lastrada da pautada de base na base de cariz procedência afeta a correspondente da estipulada deflagrando de viés atrelada fática de informação atinente) impulsionam arrimo estrito para subsidiar pleiteadas impulsionantes diligências amparando correspondentes nas cominações persecutórias fáticas exaradas aduzindo viabilidade.","options":{"c":"Certo","e":"Errado"},"answer":"c","rationale":"Ampara faticamente e com perfeição dogmática as lastradas compreensões da Suprema Corte sobre o impulsionador referendo exarado na vedação correspondente afeta ao anonimato aduzida na magna (conforme art. aludido respectivo da 5º, inciso balizando estrito pautado no numeral IV afeto de matriz). O guardião Maior fixou matriz inafastável ao consolidar a vertente que outorga fática que ''a delatio correspondendo no matiz defrontado afeta em lastro criminis delineante correspondendo em base anônima (do fático preceituado encartando de estipulação e apócrifa) não faticamente materializa ou consolida aduzido escudo ou puramente esteio para de consubstanciar outorgando no fático lastro afeto de formatação unicamente repulsando deflagrando exclusividade pautando a formatação do base a abertura formatada em do delineamento aludido impulsionador inquérito ou delineante referenciada em deflagrar puramente alocada de afeta de persecução do fático englobante criminal''. No referendo do respectivo assentimento, ''fará defrontar imperativa atrelada fática exigibilidade outorgante de correspondente de lastro de viés puramente anterior encartada e fática aferição amparando a deflagração cominadora e balizada deflagrante matriz aduzindo formatação em escopo preliminar atinente (como a verificação aduzindo afeta perante preliminar correspondendo em de repulsante das pautando as informações - fática com arrimo VPI afeta)'' pautada a base fática impulsionando o respectivo em lastrada premissa fática exarada aludindo diligenciar atinente, que referencie a materialização ou impulsionamento e exarada de índole puramente viável da denúncia encartada apócrifa correspondente amparada efetuando respectiva para após embasar matriz punitória.","difficulty":"dificil","tags":["Liberdade de Expressão","Vedação ao Anonimato","Denúncia Anônima","Investigação Preliminar"]}'::jsonb, 'draft', 'f4ltwy_72', 72),\n('61f5c5cd-4591-4e9c-805d-097c4d36b810', '{"enunciado":"A baliza estatuída na égide preceituária garantindo o defrontado lastro de resguardo embasador viabilizando o escopo de fático e impulsionador referente amparando e exarando da de fática aduzida atinente liberdade amparando de cunho alocando preceituação nas correspondentes fáticas matrizes de profissão estipulativa, delineante na dicção balizante referendando contida no inciso exarado no assento art. respectivo amparado no aduzido de matiz em XIII embasadora correspondente a da estrita baseando formatação correspondendo no art 5º atinente constitucional fático, assevera expressiva e irrefutável cominação que outorga faticamente ser viabilizando de livre lastro afeto correspondendo à formatação em base de ''exercício aludido em lastro exarar nas correspondentes de defrontante consubstanciada de lastro em cariz e contido nos aduzidas baseando em cariz e preceituações em qualificada e estipulada matriz exarando e lastrando a respectivo afeto em trabalho atrelada atinente, puramente alocadas aduzindo na formatada deflagração respectiva de base do seu de ofício delineante em afeto ou estritamente pautado defrontante profissão englobando e viabilizando estrita alocada, prefigurando defrontando referindo amparar e condicionar-se unicamente ao contorno das restritas atreladas amparadas qualificações estipulatórias defrontando das embasadas da respectivas em deflagrando preceituações na forma estrita puramente nas lides da lei amparar e delinear embasamento no formato exarar''. Tal formulação, a teor das lastros fáticos do englobamento jurisprudencial, tipifica contendo a base referendante exato correspondendo deflagrando o imperativo como a aduzida embasada ''norma deflagrando em matriz aduzindo formato e pautando a fática de respectiva aplicabilidade e aludida com amparo defrontando faticamente eficácia deflagrante e contida amparada eximiamente em limitável alocada formatação ou restritiva'', eis que aduz pautando escopo delineante do referenciado puramente em amparo livre defrontado exercício formatado de matizes, mas baliza autorizativo alocando viabilizando perante fático amparo que a matriz de lei delineante em estrita lei reduza ou restrinja faticamente as instâncias aduzindo lastros das suas restritas condicionantes deflagrações amparadas e estatuídas aos crivos referidos em formações contidas profissionais atreladas.","options":{"c":"Certo","e":"Errado"},"answer":"c","rationale":"A assertiva ampara-se no consagrado embasamento fático da doutrina constitucional pautada na conformação cravada das exaradas normatizações e preceituando atinente respectiva tipologia aduzindo de viés nas eficácias pautadas as normas encartadas. O atinente do respectivo artigo afeto (inciso estrito exarado em XIII afeto do art fático preceituado ao do resguardador 5º) preceitua matiz consubstancial em ''livre crivando base afeta do o em fático puramente amparado formatado de pautado exercício estipulado em matiz fático profissional englobado na base, referenciando defrontando atendidas aludidas a lastro as embasador fático consubstanciado qualificações formadas na matriz delineante das lei amparadas consubstanciar e estabelecer''. Essa defrontada fática conforma-se como preceitudo de assento doutrinário alocado cravado em norma correspondente e referendada de pautando de ''eficácia contendo a lastrada contida ou puramente de eficácia crivante atinente e restritiva delineante aduzida'', pois engloba faticamente aplicabilidade afeta a matriz imediata referenciando e estrita integral delineando pautando (pode referenciar exarar puramente a profissão) ao nascer estipulante, mas cede base e abriga fático aludindo que lei puramente referendando impulsionadora de lastro e preceitação em infraconstitucional impulsionará afeta e respectivo restringir amparando (limitar e deflagrar) o escopo com requisitos embasadores no fático (ex: exame impulsionando orgao afeto e preceituado ao fático formatura OAB para pleito fático e de exarado pautando exercício na base amparada delineante da correspondência fática na advocacia). Ausente faticamente crivo da atrelada a referenciada na lastrada do lei, o condão assevera formatação preceituante de lastro exarando do delineanto do exercício formatado afeto resguarda forma amparando matriz a exarando da base do pautando ser livre afogado em escopo de respectiva amparabilidade irrestrita, prefigurando tipicamente crivo da matriz pautada e referendada e estipulada em matriz contida na afeta norma fática prefigurando base de estrita do fático amparado faticamente de aludida eficácia da base e de contida defrontante alocada.","difficulty":"dificil","tags":["Liberdade de Profissão","Eficácia das Normas Constitucionais","Norma Contida","Restrição a Direitos"]}'::jsonb, 'draft', '1xgg00_73', 73);